insert into fb.settings(key,value) values ('team_code','RAMS00'),('coach_code','CHANGE-ME')
insert into fb.questions(kind,category,prompt,choices,answer,explanation,positions,scenario) values
('team','Game Plan','The H goes in motion. What''s the call?','["Luck", "Rip", "Liz", "Check"]'::jsonb,0,'H in motion = call LUCK. (Example item: edit or replace it in the Coach Panel.)','{}'::text[],'{"formation": "trips", "strength": "right", "motion": "H"}'::jsonb),
('rule','Penalties','Defensive holding in high school (NFHS). What''s the penalty?','["10 yards, no automatic first down", "10 yards + automatic first down", "5 yards + automatic first down", "15 yards"]'::jsonb,0,'NFHS: defensive holding is 10 yards with NO automatic first down.','{}'::text[],null),
('rule','Penalties','Defensive pass interference in high school (NFHS). What''s the penalty?','["15 yards, no automatic first down", "Ball placed at the spot of the foul", "15 yards + automatic first down", "10 yards"]'::jsonb,0,'NFHS: DPI is 15 yards with NO automatic first down. It is not a spot foul like the NFL.','{}'::text[],null),
('rule','Penalties','Roughing the passer. What''s the penalty?','["15 yards + automatic first down", "15 yards, no automatic first down", "10 yards", "5 yards + loss of down"]'::jsonb,0,'Roughing the passer is one of the only NFHS fouls with an automatic first down (with roughing the snapper and roughing the kicker/holder).','{}'::text[],null),
('rule','Penalties','In NFHS rules, which defensive fouls carry an automatic first down?','["Roughing the passer, kicker/holder, or snapper", "Any 15-yard defensive foul", "Pass interference and holding", "Every defensive foul"]'::jsonb,0,'NFHS: only roughing the passer, roughing the kicker/holder and roughing the snapper include an automatic first down.','{}'::text[],null),
('rule','Player Safety','Targeting in high school football. What''s the penalty?','["15 yards; ejection only if flagrant", "15 yards + automatic ejection", "10 yards", "5 yards"]'::jsonb,0,'NFHS: targeting is 15 yards. It is not an automatic disqualification unless the official rules it flagrant.','{}'::text[],null),
('rule','Player Safety','You grab the inside back collar of the runner''s jersey and pull him down. What''s the call?','["Horse-collar tackle, 15 yards", "Legal tackle", "Holding, 10 yards", "Face mask, 5 yards"]'::jsonb,0,'Grabbing the inside back or side collar (or nameplate area) and pulling the runner down is a horse-collar foul: 15 yards.','{}'::text[],null),
('rule','Player Safety','You grab the runner''s face mask and twist it. What''s the penalty?','["15 yards", "5 yards", "10 yards", "Loss of down"]'::jsonb,0,'Grasping and twisting, turning or pulling the face mask is a 15-yard personal foul.','{}'::text[],null),
('rule','Player Safety','Your helmet comes completely off during a play (not because of a foul). What happens?','["You must sit out at least the next down", "Nothing; put it back on", "15-yard penalty", "You are ejected"]'::jsonb,0,'NFHS: a player whose helmet comes completely off must leave the game for at least one down.','{}'::text[],null),
('rule','Player Safety','A teammate shows signs of a concussion. When can he return?','["Only after clearance by an appropriate health care professional", "After the next series", "When he says he feels fine", "After a team timeout"]'::jsonb,0,'NFHS: any player with concussion signs must be removed and cannot return until cleared by an appropriate health care professional.','{}'::text[],null),
('rule','Player Safety','Hitting a runner who is clearly out of bounds after the play. What''s the penalty?','["15-yard personal foul", "5 yards", "10 yards", "No foul if he still has the ball"]'::jsonb,0,'A late hit out of bounds is a personal foul: 15 yards.','{}'::text[],null),
('rule','Pre-Snap','Before the snap, the 3 Tech jumps into the neutral zone and touches the guard. What''s the call?','["Encroachment on the defense, 5 yards", "False start on the offense", "Legal if he gets back", "Offside, 15 yards"]'::jsonb,0,'Entering the neutral zone and contacting an opponent before the snap is defensive encroachment: a 5-yard dead-ball foul.','{}'::text[],null),
('rule','Pre-Snap','A defender reaches across and touches the football before it''s snapped. What''s the call?','["Encroachment, 5 yards", "Legal; the ball is live", "Delay of game on the offense", "Unsportsmanlike, 15 yards"]'::jsonb,0,'Defenders may not touch the ball before the snap. That is encroachment: 5 yards.','{}'::text[],null),
('rule','Pre-Snap','How wide is the neutral zone?','["The length of the football", "1 yard", "2 yards", "5 yards"]'::jsonb,0,'The neutral zone is the space between the two ends of the ball (the length of the football).','{}'::text[],null),
('rule','Pre-Snap','An offensive lineman flinches after getting set. What''s the call?','["False start, 5 yards", "Encroachment on the defense", "Illegal motion, 10 yards", "No foul"]'::jsonb,0,'Any movement by a set offensive lineman that simulates the snap is a false start: 5 yards, dead ball.','{}'::text[],null),
('rule','Motion','How many offensive players can be in motion at the snap?','["One", "Two", "Any backs", "None"]'::jsonb,0,'NFHS: only one player may be in motion at the snap.','{}'::text[],null),
('rule','Motion','The motion man is running toward the defense''s goal line at the snap. Is that legal?','["No: illegal motion, 5 yards", "Yes, if he is a back", "Yes, if he started behind the QB", "No: 15 yards"]'::jsonb,0,'NFHS: a player in motion at the snap may not be moving toward the opponent''s goal line. That is illegal motion: 5 yards.','{}'::text[],null),
('rule','Formation','At least how many offensive linemen must wear numbers 50 to 79?','["5", "4", "6", "7"]'::jsonb,0,'NFHS: at least five players on the line of scrimmage must wear numbers 50-79 (scrimmage-kick exception aside).','{}'::text[],null),
('rule','Formation','What''s the most players the offense can have in the backfield?','["4", "3", "5", "No limit"]'::jsonb,0,'NFHS: no more than four backs. Everyone else must be on the line.','{}'::text[],null),
('rule','Formation','The offense snaps the ball with 12 players on the field. What''s the penalty?','["Illegal participation, 15 yards", "5 yards", "Loss of down", "Replay the down"]'::jsonb,0,'NFHS: 12 or more players on the field at the snap is illegal participation, 15 yards.','{}'::text[],null),
('rule','Formation','Which offensive players are eligible to catch a forward pass?','["Ends and backs not numbered 50-79", "Anyone behind the line", "Only receivers split wide", "Any player with a number under 90"]'::jsonb,0,'Eligible receivers are the players on the ends of the line and the backs, as long as they are not numbered 50-79.','{}'::text[],null),
('rule','Blocking','Where is blocking below the waist legal in NFHS?','["Only inside the free-blocking zone", "Anywhere on the field", "Only on kicks", "Nowhere"]'::jsonb,0,'NFHS: blocking below the waist is illegal outside the free-blocking zone. Inside it, linemen in the zone at the snap may block opposing linemen low on the initial charge.','{}'::text[],null),
('rule','Blocking','How big is the free-blocking zone?','["4 yards each side of the snapper, 3 yards behind each line", "5 yards each side, 5 yards deep", "Tackle to tackle only", "2 yards each side, 2 yards deep"]'::jsonb,0,'The free-blocking zone extends 4 yards laterally each side of the snapper and 3 yards behind each line of scrimmage.','{}'::text[],null),
('rule','Blocking','A guard is blocking you high while the tackle cuts your knees. What''s that?','["Chop block, 15 yards", "Legal double team", "Holding, 10 yards", "Clipping, 5 yards"]'::jsonb,0,'A high-low combination on a player already engaged with a teammate is a chop block: 15 yards.','{}'::text[],null),
('rule','Blocking','Clipping (a block from behind at or below the waist, not on the runner). What''s the penalty?','["15 yards", "10 yards", "5 yards", "Loss of down"]'::jsonb,0,'Clipping is a 15-yard foul.','{}'::text[],null),
('rule','Blocking','The offense holds in its own end zone. What''s the result?','["Safety: 2 points for the defense", "Replay the down", "Ball at the 1-yard line", "Touchback"]'::jsonb,0,'A foul by the offense in its own end zone, enforced from there, results in a safety: 2 points for the defense.','{}'::text[],null),
('rule','Passing','The QB throws the ball away to avoid a sack with no receiver in the area. What''s the penalty?','["Intentional grounding: loss of down + 5 yards from the spot of the pass", "15 yards", "10 yards, replay the down", "No foul in high school"]'::jsonb,0,'NFHS intentional grounding: loss of down and 5 yards from the spot of the pass.','{}'::text[],null),
('rule','Passing','An offensive lineman is 4 yards downfield when a forward pass is thrown past the line. What''s the call?','["Ineligible downfield, 5 yards", "Offensive pass interference, 15 yards", "Legal", "Holding, 10 yards"]'::jsonb,0,'NFHS: ineligible receivers may not be more than 2 yards beyond the line when a pass that crosses the line is thrown. Penalty: 5 yards.','{}'::text[],null),
('rule','Passing','A backward pass (lateral) hits the ground. Who can recover it?','["Either team", "Only the offense", "Nobody; it''s dead like an incomplete pass", "Only the player who threw it"]'::jsonb,0,'A backward pass that hits the ground is a live ball. Either team can recover it.','{}'::text[],null),
('rule','Turnovers','You strip the ball and your teammate scoops it on the run. Can he advance it in high school?','["Yes, a fumble can be advanced", "No, it''s dead where recovered", "Only on 4th down", "Only past midfield"]'::jsonb,0,'NFHS: a fumble is a live ball and can be advanced by either team.','{}'::text[],null),
('rule','Turnovers','On a try (PAT/2-point), you intercept the pass. Can you score?','["No. The ball is dead when the defense gets possession", "Yes, 2 points", "Yes, 6 points", "Yes, 1 point"]'::jsonb,0,'NFHS: on a try the ball becomes dead when the defense secures possession. The defense cannot score on a try.','{}'::text[],null),
('rule','Scoring','A safety is worth how many points?','["2", "1", "3", "6"]'::jsonb,0,'A safety is 2 points, and the team that gave it up free-kicks from its own 20-yard line.','{}'::text[],null),
('rule','Scoring','After a safety, where does the team that was tackled free-kick from?','["Its own 20-yard line", "Its own 40-yard line", "Its own 35-yard line", "Its own 30-yard line"]'::jsonb,0,'After a safety, the team scored on free-kicks (kick or punt) from its own 20.','{}'::text[],null),
('rule','Scoring','Where is the ball snapped for a try (PAT or 2-point) in high school?','["The 3-yard line", "The 2-yard line", "The 15-yard line", "The 5-yard line"]'::jsonb,0,'NFHS: the try is snapped from the 3-yard line. 1 point by kick, 2 points by run or pass.','{}'::text[],null),
('rule','Kicking','Where does the kicking team kick off from in NFHS?','["Its own 40-yard line", "Its own 35-yard line", "Its own 30-yard line", "Its own 45-yard line"]'::jsonb,0,'NFHS: kickoffs are from the kicking team''s 40-yard line.','{}'::text[],null),
('rule','Kicking','After a touchback, where is the ball snapped?','["The 20-yard line", "The 25-yard line", "The 30-yard line", "The 10-yard line"]'::jsonb,0,'NFHS: after a touchback the ball is snapped at the 20-yard line.','{}'::text[],null),
('rule','Kicking','What is a valid fair-catch signal?','["One hand fully extended above the head, waved side to side", "Both arms crossed over the chest", "Pointing at the ground", "Raising a hand without waving"]'::jsonb,0,'Valid fair catch signal: one hand fully extended above the head and waved from side to side.','{}'::text[],null),
('rule','Kicking','On a punt, you run into the punter but don''t rough him. What''s the penalty?','["Running into the kicker, 5 yards", "Roughing the kicker, 15 + first down", "10 yards", "No foul"]'::jsonb,0,'Running into the kicker is 5 yards. Roughing the kicker is 15 yards plus an automatic first down.','{}'::text[],null),
('rule','Kicking','The kicking team interferes with a returner''s chance to catch the ball. What''s the penalty?','["Kick-catch interference, 15 yards", "5 yards", "Re-kick, no yardage", "10 yards"]'::jsonb,0,'Kick-catch interference is a 15-yard foul.','{}'::text[],null),
('rule','Conduct','A player gets two unsportsmanlike conduct fouls in one game. What happens?','["He is disqualified", "30 yards", "Nothing extra", "He sits one quarter"]'::jsonb,0,'NFHS: a player (or coach) with two unsportsmanlike fouls in a game is disqualified.','{}'::text[],null),
('rule','Conduct','A player throws a punch in a fight. What happens?','["Disqualification + 15 yards", "15 yards only", "5 yards", "Warning first"]'::jsonb,0,'Fighting results in disqualification and a 15-yard penalty.','{}'::text[],null),
('rule','Game Basics','How long is a quarter in high school football?','["12 minutes", "15 minutes", "10 minutes", "8 minutes"]'::jsonb,0,'NFHS quarters are 12 minutes.','{}'::text[],null),
('rule','Game Basics','How many timeouts does each team get per half?','["3", "2", "4", "5"]'::jsonb,0,'NFHS: three timeouts per team per half.','{}'::text[],null),
('rule','Game Basics','Which rulebook does the LHSAA use for football?','["NFHS", "NCAA", "NFL", "Its own rulebook only"]'::jsonb,0,'The LHSAA plays by NFHS football rules, with state-association adjustments where NFHS allows them.','{}'::text[],null),
('rule','Game Basics','In the NFHS overtime option, where does each team start its possession?','["The opponent''s 10-yard line", "The 25-yard line", "Its own 25-yard line", "Midfield"]'::jsonb,0,'NFHS overtime (a state-association option): each team gets a series from the 10-yard line.','{}'::text[],null);
